// Arquivo: src/pages/ong/OngReportsPage/OngReportsPage.jsx

import React, { useState, useEffect } from 'react';
import jsPDF from 'jspdf';
import autoTable from 'jspdf-autotable';

import ContentWrapper from '../../../components/ui/ContentWrapper/ContentWrapper';
import ReportSection from '../../../components/ui/ReportSection/ReportSection';
import InputField from '../../../components/ui/InputField/InputField';
import api from '../../../api/api';
import styles from './OngReportsPage.module.css';

const headerTranslations = {
  id: 'ID', name: 'Nome', cpf: 'CPF', seal_balance: 'Saldo de Selos',
  used_seals: 'Selos Usados', user_id: 'ID do Usuário', user_name: 'Nome do Usuário',
  user_cpf: 'CPF do Usuário', redemption_date: 'Data do Resgate',
  seals_redeemed: 'Selos Resgatados', remaining_balance: 'Saldo Restante',
  dependents_count: 'Dependentes',
  logradouro: 'Arruamento/Rua', numero: 'Nº', complemento: 'Complemento',
  bairro: 'Bairro', cidade: 'Cidade', estado: 'UF', cep: 'CEP'
};

const translateHeader = (headerKey) => headerTranslations[headerKey] || headerKey;

const formatDateTime = (dateString) => {
  if (!dateString) return '-';
  const date = new Date(dateString);
  return date.toLocaleString('pt-BR', {
    day: '2-digit', month: '2-digit', year: 'numeric',
    hour: '2-digit', minute: '2-digit'
  });
};

const formatDateOnly = (dateString) => {
  if (!dateString) return '-';
  const date = new Date(dateString);
  const userTimezoneOffset = date.getTimezoneOffset() * 60000;
  const correctedDate = new Date(date.getTime() + userTimezoneOffset);
  return correctedDate.toLocaleDateString('pt-BR');
};

const OngReportsPage = ({ currentUser }) => {
  const [reportData, setReportData] = useState(null);
  const [ongName, setOngName] = useState('Minha Organização');
  
  const [userSearchTerm, setUserSearchTerm] = useState('');
  const [auditSearchTerm, setAuditSearchTerm] = useState('');
  
  const [loading, setLoading] = useState(true);
  const [loadingAudit, setLoadingAudit] = useState(false);
  const [auditLogs, setAuditLogs] = useState([]);
  
  const [isUserProfileOpen, setIsUserProfileOpen] = useState(false);
  const [selectedUserProfile, setSelectedUserProfile] = useState(null);
  const [userProofs, setUserProofs] = useState([]);
  const [loadingUserProofs, setLoadingUserProofs] = useState(false);

  const myOngId = currentUser?.ong_id || currentUser?.id;

  useEffect(() => {
    if (!myOngId) return;
    const fetchOngDetails = async () => {
      try {
        const response = await api.get(`/ongs/${myOngId}`); 
        setOngName(response.data.fantasy_name || 'Organização');
      } catch (error) {
        console.error("Erro ao buscar nome da organização:", error);
        setOngName(currentUser?.ong_name || 'Minha Organização');
      }
    };
    fetchOngDetails();
  }, [myOngId, currentUser]);

  useEffect(() => {
    if (!myOngId) { setLoading(false); return; }
    const fetchReportData = async () => {
      setLoading(true);
      try {
        const params = { ongId: myOngId, search: userSearchTerm || undefined };
        const response = await api.get('/reports', { params });
        setReportData(response.data);
      } catch (error) {
        console.error("Erro ao buscar dados dos relatórios:", error);
        setReportData(null);
      } finally { setLoading(false); }
    };
    
    const debounceFetch = setTimeout(() => { fetchReportData(); }, 300);
    return () => clearTimeout(debounceFetch);
  }, [myOngId, userSearchTerm]);

  useEffect(() => {
    if (!myOngId) return;
    const fetchAuditLogs = async () => {
      setLoadingAudit(true);
      try {
        const response = await api.get(`/proofs/log/${myOngId}`);
        setAuditLogs(response.data);
      } catch (error) {
        console.error("Erro ao carregar auditoria:", error);
        setAuditLogs([]);
      } finally { setLoadingAudit(false); }
    };
    fetchAuditLogs();
  }, [myOngId]);

  const handleOpenUserProfile = async (user) => {
    setSelectedUserProfile(user);
    setIsUserProfileOpen(true);
    setLoadingUserProofs(true);
    try {
      const profileRes = await api.get(`/users/${user.id}/details`);
      const detailedUser = {
        ...profileRes.data.usuario,
        dependents: profileRes.data.dependentes || []
      };
      
      // Parse de campos JSON do banco, caso venham como string
      try {
          detailedUser.social_benefits = detailedUser.social_benefits ? JSON.parse(detailedUser.social_benefits) : [];
          detailedUser.public_services_access = detailedUser.public_services_access ? JSON.parse(detailedUser.public_services_access) : [];
          detailedUser.main_needs = detailedUser.main_needs ? JSON.parse(detailedUser.main_needs) : [];
      } catch(e) {}

      setSelectedUserProfile({ ...user, ...detailedUser });

      const response = await api.get(`/proofs/user/${user.id}`);
      const ongProofs = response.data.filter(p => p.ong_id === myOngId);
      setUserProofs(ongProofs);
    } catch (error) {
      console.error("Erro ao buscar provas do usuário:", error);
      setUserProofs([]);
    } finally {
      setLoadingUserProofs(false);
    }
  };

  const handleDownloadUserDossier = () => {
    if (!selectedUserProfile) return;
    const doc = new jsPDF();
    const p = selectedUserProfile;
    const PRINT_DATE_TIME = new Date().toLocaleString('pt-BR');

        const LOGO_BASE64 = "data:image/png;base64,"; // <-- COLE AQUI O BASE64 DA LOGO SELO CIDADANIA

    if (LOGO_BASE64 && LOGO_BASE64.trim() !== "") {
        try {
            doc.addImage(LOGO_BASE64, 'PNG', 14, 10, 25, 25);
        } catch (e) {
            doc.setFontSize(10);
            doc.setTextColor(150);
            doc.text("Selo Cidadania", 14, 20);
        }
    } else {
        doc.setFontSize(10);
        doc.setTextColor(150);
        doc.text("Selo Cidadania", 14, 20);
    }

    doc.setFontSize(9);
    doc.setTextColor(100);
    doc.text(`Organização (OSC): ${ongName}`, 196, 15, { align: 'right' });
    doc.text(`Relatório gerado em: ${PRINT_DATE_TIME}`, 196, 20, { align: 'right' });

    doc.setFontSize(18);
    doc.setTextColor(0);
    doc.setFont("helvetica", "bold");
    doc.text(`Relatório do Beneficiário`, 105, 35, { align: 'center' });
    
    doc.setFontSize(14);
    doc.text(p.name, 105, 43, { align: 'center' });
    doc.setFont("helvetica", "normal");

    const formattedAddress = p.logradouro ?
        `${p.logradouro}, nº ${p.numero}${p.complemento ? ' (' + p.complemento + ')' : ''}, ${p.bairro}, ${p.cidade}/${p.estado}. CEP: ${p.cep}`
        : 'Endereço não cadastrado.';

    // Montando Tabela 1: Identificação Básica
    autoTable(doc, {
      startY: 50,
      head: [['Identificação e Contato', '']],
      body: [
        ['CPF', p.cpf || 'Não informado'],
        ['RG', p.rg || 'Não informado'],
        ['Data de Nascimento', formatDateOnly(p.birth_date)],
        ['Nome da Mãe', p.mothers_name || 'Não informado'],
        ['Gênero / Orientação Sexual', `${p.gender || '-'} / ${p.sexual_orientation || '-'}`],
        ['E-mail', p.email || 'Não informado'],
        ['Telefone / WhatsApp', p.phone || 'Não informado'],
        ['Endereço Cadastrado', formattedAddress] 
      ],
      theme: 'grid',
      headStyles: { fillColor: [245, 158, 11] }, 
      styles: { fontSize: 9 },
      columnStyles: { 0: { cellWidth: 60, fontStyle: 'bold' } }
    });

    // Montando Tabela 2: Mapeamento Social
    autoTable(doc, {
        startY: doc.lastAutoTable.finalY + 8,
        head: [['Mapeamento Social e Habitacional', '']],
        body: [
          ['Tempo de Residência', p.residence_time || 'Não informado'],
          ['Tipo de Habitação', p.housing_type || 'Não informado'],
          ['Tamanho da Família / Cômodos', `${p.household_size || '-'} pessoas / ${p.rooms_count || '-'} cômodos`],
          ['Infraestrutura (Água / Esgoto / Luz)', `${p.has_water ? 'Sim':'Não'} / ${p.has_sanitation ? 'Sim':'Não'} / ${p.has_electricity ? 'Sim':'Não'}`],
          ['Escolaridade', p.education_level || 'Não informado'],
          ['Situação de Trabalho / Renda', `${p.employment_status || '-'} / R$ ${p.family_income || '-'}`],
          ['Povos Tradicionais', p.traditional_community || 'Não'],
          ['Benefícios Sociais', Array.isArray(p.social_benefits) ? p.social_benefits.join(', ') : 'Não informado'],
          ['Acesso a Serviços Públicos', Array.isArray(p.public_services_access) ? p.public_services_access.join(', ') : 'Não informado'],
          ['Maiores Necessidades', Array.isArray(p.main_needs) ? p.main_needs.join(', ') : 'Não informado']
        ],
        theme: 'grid',
        headStyles: { fillColor: [16, 185, 129] }, // Verde para mapeamento
        styles: { fontSize: 9 },
        columnStyles: { 0: { cellWidth: 60, fontStyle: 'bold' } }
      });

    const deps = p.dependents || [];
    const dependentsBody = deps.map(d => [
      d.full_name || d.name,
      formatDateOnly(d.birth_date),
      d.cpf || '-',
      d.kinship || '-'
    ]);

    autoTable(doc, {
      startY: doc.lastAutoTable.finalY + 8,
      head: [['Dependentes', 'Data Nascimento', 'CPF Dependente', 'Parentesco']],
      body: dependentsBody.length > 0 ? dependentsBody : [['Nenhum dependente cadastrado.', '', '', '']],
      theme: 'grid',
      headStyles: { fillColor: [59, 130, 246] }, // Azul
      styles: { fontSize: 9 }
    });

    const proofsBody = userProofs.map(proof => [
      proof.title,
      formatDateOnly(proof.created_at),
      proof.status === 'approved' ? 'Aprovada' : proof.status === 'rejected' ? 'Rejeitada' : 'Pendente',
      proof.evaluator_name || '-',
      proof.feedback_message || '-'
    ]);

    autoTable(doc, {
      startY: doc.lastAutoTable.finalY + 8,
      head: [['Atividade/Prova Social', 'Data Envio', 'Status', 'Avaliador', 'Feedback do Avaliador']],
      body: proofsBody.length > 0 ? proofsBody : [['Nenhuma prova social enviada.', '', '', '', '']],
      theme: 'grid',
      headStyles: { fillColor: [139, 92, 246] }, // Indigo
      styles: { fontSize: 8 }
    });

    const userRedemptions = reportData?.allRedemptions ? reportData.allRedemptions.filter(r => r.user_id === p.id) : [];
    const redemptionsBody = userRedemptions.map(r => [
      r.prize_name,
      formatDateOnly(r.redemption_date),
      `-${r.seals_redeemed} Selos`
    ]);

    autoTable(doc, {
      startY: doc.lastAutoTable.finalY + 8,
      head: [['Histórico de Resgates', 'Data do Resgate', 'Custo em Selos']],
      body: redemptionsBody.length > 0 ? redemptionsBody : [['Nenhum resgate efetuado.', '', '']],
      theme: 'grid',
      headStyles: { fillColor: [236, 72, 153] }, // Rosa
      styles: { fontSize: 9 }
    });

    const totalPages = doc.internal.getNumberOfPages();
    for (let i = 1; i <= totalPages; i++) {
        doc.setPage(i);
        doc.setFontSize(8);
        doc.setTextColor(150);
        doc.text(`Página ${i} de ${totalPages} - Relatório oficial gerado pelo Sistema Selo Cidadania`, 105, 285, { align: 'center' });
    }

    doc.save(`Relatorio_${p.name.replace(/ /g, '_')}.pdf`);
  };

  const sortedUsers = reportData?.allUsers 
    ? [...reportData.allUsers].sort((a, b) => a.name.localeCompare(b.name)) 
    : [];

  const filteredLogs = auditLogs.filter(log => {
    const term = auditSearchTerm.toLowerCase();
    return (
      (log.sender_name && log.sender_name.toLowerCase().includes(term)) ||
      (log.activity_title && log.activity_title.toLowerCase().includes(term)) ||
      (log.evaluator_name && log.evaluator_name.toLowerCase().includes(term))
    );
  });

  const groupedLogs = filteredLogs.reduce((acc, log) => {
    const userName = log.sender_name || 'Utilizador Desconhecido';
    if (!acc[userName]) acc[userName] = [];
    acc[userName].push(log);
    return acc;
  }, {});

  const sortedLogUsers = Object.keys(groupedLogs).sort((a, b) => a.localeCompare(b));

  if (loading && !reportData) {
    return <ContentWrapper title="Meus Relatórios"><p>A carregar relatórios da organização...</p></ContentWrapper>;
  }

  const userRedemptions = selectedUserProfile && reportData?.allRedemptions 
    ? reportData.allRedemptions.filter(r => r.user_id === selectedUserProfile.id) 
    : [];

  return (
    <ContentWrapper title="Meus Relatórios">
      
      {reportData ? (
        <>
          <div className={styles.reportBlock}>
            <ReportSection title={`Visão Geral de ${ongName}`}>
              <div className={styles.sectionHeader}>
                <div className={styles.statCard} style={{ backgroundColor: '#e0f2fe' }}>
                  <p>Beneficiários Cadastrados</p>
                  <span>{reportData.generalStats?.totalUsers || 0}</span>
                </div>
                <div className={styles.statCard} style={{ backgroundColor: '#d1fae5' }}>
                  <p>Selos Distribuídos/Ativos</p>
                  <span>{reportData.generalStats?.totalSealsInCirculation || 0}</span>
                </div>
                <div className={styles.statCard} style={{ backgroundColor: '#fee2e2' }}>
                  <p>Selos Resgatados (Total)</p>
                  <span>{reportData.generalStats?.totalSealsRedeemed || 0}</span>
                </div>
              </div>
            </ReportSection>
          </div>

          <div className={styles.reportBlock}>
            <ReportSection title="Meus Beneficiários (A-Z)">
              <div className={styles.sectionHeader}>
                <InputField
                  label="Filtrar Beneficiários"
                  placeholder="Nome ou CPF..."
                  value={userSearchTerm}
                  onChange={(e) => setUserSearchTerm(e.target.value)}
                />
              </div>
              
              <div className={styles.groupedListContainer}>
                {sortedUsers.length > 0 ? sortedUsers.map(user => (
                  <div 
                    key={user.id} 
                    className={styles.userListItemClickable} 
                    onClick={() => handleOpenUserProfile(user)}
                    title="Clique para ver o dossiê completo"
                  >
                    <div className={styles.userMainInfo}>
                      <span className={styles.userAvatarSm}>{user.name.charAt(0).toUpperCase()}</span>
                      <div>
                        <h4 className={styles.userNameTitle}>{user.name}</h4>
                        <span className={styles.userSubText}>CPF: {user.cpf}</span>
                      </div>
                    </div>
                    <div className={styles.userStats}>
                      <div className={styles.statPill}>
                        <strong>{user.seal_balance}</strong> Selos
                      </div>
                    </div>
                  </div>
                )) : (
                  <p className={styles.emptyMessage}>Nenhum beneficiário encontrado.</p>
                )}
              </div>
            </ReportSection>
          </div>

          <div className={styles.reportBlock}>
            <ReportSection title="Auditoria de Provas Sociais e Atividades (A-Z)">
              <div className={styles.sectionHeader}>
                <InputField
                  label="Filtrar Histórico"
                  placeholder="Pesquisar por nome do beneficiário, atividade ou avaliador..."
                  value={auditSearchTerm}
                  onChange={(e) => setAuditSearchTerm(e.target.value)}
                />
              </div>

              <div className={styles.groupedListContainer}>
                {loadingAudit ? (
                  <p className={styles.loadingText}>A carregar auditoria...</p>
                ) : sortedLogUsers.length > 0 ? (
                  sortedLogUsers.map(userName => (
                    <div key={userName} className={styles.userGroup}>
                      <div className={styles.userGroupHeader}>
                        <div className={styles.userInfo}>
                          <span className={styles.userAvatarSm}>{userName.charAt(0).toUpperCase()}</span>
                          <h4 className={styles.userNameTitle}>{userName}</h4>
                        </div>
                        <span className={styles.badgeCount}>{groupedLogs[userName].length} registo(s)</span>
                      </div>

                      <div className={styles.logGrid}>
                        {groupedLogs[userName].map(log => (
                          <div key={log.id} className={styles.logCard}>
                            <div className={styles.logHeader}>
                              <h5>{log.activity_title} <span className={styles.sealBadge}>+{log.seal_value} Selos</span></h5>
                            </div>

                            <div className={styles.logBody}>
                              <div className={styles.logRow}>
                                <span><strong>Enviado em:</strong> {formatDateTime(log.sent_at)}</span>
                              </div>
                              <div className={styles.logRow}>
                                <span><strong>Avaliador:</strong> {log.evaluator_name || 'Automático'}</span>
                                <span><strong>Data:</strong> {formatDateTime(log.evaluated_at)}</span>
                              </div>
                              {log.feedback_message && (
                                <div className={styles.logRow} style={{ marginTop: '10px', backgroundColor: '#f1f5f9', padding: '8px', borderRadius: '4px' }}>
                                  <span><strong>Feedback:</strong> {log.feedback_message}</span>
                                </div>
                              )}
                            </div>

                            <div className={styles.logFooter}>
                              <span className={log.status === 'approved' ? styles.statusApproved : styles.statusRejected}>
                                {log.status === 'approved' ? 'Aprovada' : 'Rejeitada'}
                              </span>
                            </div>
                          </div>
                        ))}
                      </div>
                    </div>
                  ))
                ) : (
                  <p className={styles.emptyMessage}>Nenhum registo de avaliação encontrado.</p>
                )}
              </div>
            </ReportSection>
          </div>
        </>
      ) : (
        !loading && <p className={styles.emptyMessage}>Não foi possível carregar os dados da sua organização.</p>
      )}

      {isUserProfileOpen && selectedUserProfile && (
        <div className={styles.customOverlay} onClick={() => setIsUserProfileOpen(false)}>
          <div className={styles.customModalLg} onClick={(e) => e.stopPropagation()}>
            
            <div className={styles.customModalHeader}>
              <div className={styles.modalHeaderTitle}>
                <h3>Dossiê Completo do Beneficiário</h3>
              </div>
              <button className={styles.closeBtn} onClick={() => setIsUserProfileOpen(false)}>×</button>
            </div>

            <div className={styles.customModalBody}>
              <div className={styles.profileHeaderCard}>
                <div className={styles.profileHeaderLeft}>
                  <div className={styles.profileAvatarLg}>{selectedUserProfile.name.charAt(0).toUpperCase()}</div>
                  <div className={styles.profileHeaderInfo}>
                    <h2>{selectedUserProfile.name}</h2>
                    <p>Membro desde: {formatDateOnly(selectedUserProfile.created_at)}</p>
                  </div>
                </div>
                <button className={styles.downloadBtn} onClick={handleDownloadUserDossier}>
                  📥 Gerar PDF
                </button>
              </div>

              <div className={styles.profileGridLg}>
                
                <div className={styles.profileSideCol}>
                  <div className={styles.profileSectionWhite}>
                    <h4 className={styles.profileSectionTitle}>Dados Pessoais e Residenciais</h4>
                    <ul className={styles.profileDataList}>
                      <li><strong>CPF:</strong> {selectedUserProfile.cpf || '-'}</li>
                      <li><strong>RG:</strong> {selectedUserProfile.rg || '-'}</li>
                      <li><strong>Data Nasc:</strong> {formatDateOnly(selectedUserProfile.birth_date)}</li>
                      <li><strong>Nome da Mãe:</strong> {selectedUserProfile.mothers_name || '-'}</li>
                      <li><strong>E-mail:</strong> {selectedUserProfile.email || '-'}</li>
                      <li><strong>Telefone:</strong> {selectedUserProfile.phone || '-'}</li>
                      <hr style={{margin: '10px 0', border: 'none', borderTop: '1px dashed #ccc'}}/>
                      <li>
                          <strong>Endereço:</strong>
                          <span style={{fontSize: '0.9rem', color: '#555', marginTop: '5px', display: 'block'}}>
                              {selectedUserProfile.logradouro ? 
                                `${selectedUserProfile.logradouro}, nº ${selectedUserProfile.numero}${selectedUserProfile.complemento ? ' ('+selectedUserProfile.complemento+')' : ''}. ${selectedUserProfile.bairro}. ${selectedUserProfile.cidade}/${selectedUserProfile.estado}. CEP: ${selectedUserProfile.cep}`
                                : 'Não informado'}
                          </span>
                      </li>
                      <li><strong>Tempo no Local:</strong> {selectedUserProfile.residence_time || '-'}</li>
                      <li><strong>Tipo:</strong> {selectedUserProfile.housing_type || '-'}</li>
                    </ul>
                  </div>

                  <div className={styles.profileSectionWhite}>
                    <h4 className={styles.profileSectionTitle}>Condições e Mapeamento</h4>
                    <ul className={styles.profileDataList}>
                      <li><strong>Pessoas na casa:</strong> {selectedUserProfile.household_size || '-'}</li>
                      <li><strong>Cômodos:</strong> {selectedUserProfile.rooms_count || '-'}</li>
                      <li><strong>Água Encanada:</strong> {selectedUserProfile.has_water ? 'Sim' : 'Não'}</li>
                      <li><strong>Saneamento:</strong> {selectedUserProfile.has_sanitation ? 'Sim' : 'Não'}</li>
                      <li><strong>Energia Elétrica:</strong> {selectedUserProfile.has_electricity ? 'Sim' : 'Não'}</li>
                      <hr style={{margin: '10px 0', border: 'none', borderTop: '1px dashed #ccc'}}/>
                      <li><strong>Escolaridade:</strong> {selectedUserProfile.education_level || '-'}</li>
                      <li><strong>Situação trab:</strong> {selectedUserProfile.employment_status || '-'}</li>
                      <li><strong>Renda Familiar:</strong> {selectedUserProfile.family_income ? `R$ ${selectedUserProfile.family_income}` : '-'}</li>
                      <li><strong>Povos Tradicionais:</strong> {selectedUserProfile.traditional_community || 'Não'}</li>
                    </ul>
                    <div style={{marginTop: '15px'}}>
                      <strong>Benefícios Sociais:</strong>
                      <div className={styles.pillsContainer}>
                        {Array.isArray(selectedUserProfile.social_benefits) && selectedUserProfile.social_benefits.length > 0 
                          ? selectedUserProfile.social_benefits.map(b => <span key={b} className={styles.pillItem}>{b}</span>) 
                          : <span className={styles.emptyTextSm}>Nenhum</span>}
                      </div>
                    </div>
                    <div style={{marginTop: '15px'}}>
                      <strong>Maiores Necessidades:</strong>
                      <div className={styles.pillsContainer}>
                        {Array.isArray(selectedUserProfile.main_needs) && selectedUserProfile.main_needs.length > 0 
                          ? selectedUserProfile.main_needs.map(n => <span key={n} className={styles.pillItem}>{n}</span>) 
                          : <span className={styles.emptyTextSm}>Não informado</span>}
                      </div>
                    </div>
                  </div>

                  <div className={styles.profileSectionWhite}>
                    <h4 className={styles.profileSectionTitle}>Dependentes ({selectedUserProfile.dependents?.length || 0})</h4>
                    {selectedUserProfile.dependents && selectedUserProfile.dependents.length > 0 ? (
                      <ul className={styles.dependentsList}>
                        {selectedUserProfile.dependents.map((dep, i) => (
                          <li key={i}>
                            <strong>{dep.name || dep.full_name}</strong>
                            <span>Nasc: {formatDateOnly(dep.birth_date)} | {dep.kinship}</span>
                          </li>
                        ))}
                      </ul>
                    ) : <p className={styles.emptyTextSm}>Nenhum dependente.</p>}
                  </div>
                </div>

                <div className={styles.profileMainCol}>
                  
                  <div className={styles.profileSectionWhite}>
                    <h4 className={styles.profileSectionTitle}>Carteira: {selectedUserProfile.seal_balance} Selos</h4>
                  </div>

                  <div className={styles.profileSectionWhite}>
                    <h4 className={styles.profileSectionTitle}>Histórico de Provas ({userProofs.length})</h4>
                    {loadingUserProofs ? (
                      <p className={styles.emptyTextSm}>A carregar...</p>
                    ) : userProofs.length > 0 ? (
                      <ul className={styles.historyList}>
                        {userProofs.map(proof => (
                          <li key={proof.id} className={styles.proofHistoryItem}>
                            <div className={styles.historyHeaderRow}>
                              <div className={styles.historyMain}>
                                <strong>{proof.title}</strong>
                                <span className={styles.historyDate}>Enviado: {formatDateTime(proof.created_at)}</span>
                              </div>
                              <span className={
                                proof.status === 'approved' ? styles.statusApprovedSm :
                                proof.status === 'rejected' ? styles.statusRejectedSm :
                                styles.statusPendingSm
                              }>
                                {proof.status === 'approved' ? 'Aprovada' : proof.status === 'rejected' ? 'Rejeitada' : 'Pendente'}
                              </span>
                            </div>
                            
                            {proof.status !== 'pending' && (
                              <div className={styles.proofEvalInfo}>
                                <span><strong>Por:</strong> {proof.evaluator_name || '-'}</span>
                                <span><strong>Em:</strong> {formatDateTime(proof.evaluated_at)}</span>
                                {proof.feedback_message && (
                                  <span style={{display: 'block', width: '100%', marginTop: '8px', color: '#b45309'}}>
                                    <strong>Obs:</strong> {proof.feedback_message}
                                  </span>
                                )}
                              </div>
                            )}
                          </li>
                        ))}
                      </ul>
                    ) : <p className={styles.emptyTextSm}>Sem provas nesta OSC.</p>}
                  </div>

                  <div className={styles.profileSectionWhite}>
                    <h4 className={styles.profileSectionTitle}>Resgates ({userRedemptions.length})</h4>
                    {userRedemptions.length > 0 ? (
                      <ul className={styles.historyList}>
                        {userRedemptions.map(redemption => (
                          <li key={redemption.id}>
                            <div className={styles.historyMain}>
                              <strong>{redemption.prize_name}</strong>
                              <span className={styles.historyDate}>{formatDateTime(redemption.redemption_date)}</span>
                            </div>
                            <span className={styles.negativeSeals}>-{redemption.seals_redeemed}</span>
                          </li>
                        ))}
                      </ul>
                    ) : <p className={styles.emptyTextSm}>Nenhum resgate.</p>}
                  </div>

                </div>
              </div>
            </div>
          </div>
        </div>
      )}

    </ContentWrapper>
  );
};

export default OngReportsPage;